1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Design Directions</title>
7	<!-- Stage 4 design file only: static HTML + CSS, no scripts, no external assets. Colours match ui-design.md "Design direction". -->
8	<style>
9	  :root {
10	    --page-bg: #F3F4F6; --page-text: #1A1D21; --page-muted: #555B64; --page-rule: #D9DCE1;
11	    --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
12	  }
13	  * { box-sizing: border-box; }
14	  body { margin: 0; background: var(--page-bg); color: var(--page-text); font-family: var(--font); line-height: 1.5; -webkit-font-smoothing: antialiased; }
15	  .page { max-width: 1240px; margin: 0 auto; padding: 40px 24px 56px; }
16	  .page-head { margin-bottom: 32px; }
17	  .page-head p { margin: 0; font-size: 13px; letter-spacing: .08em; text-transform: uppercase; color: var(--page-muted); font-weight: 600; }
18	  .page-head h1 { margin: 6px 0 8px; font-size: 28px; line-height: 1.2; letter-spacing: -.01em; }
19	  .page-head .note { text-transform: none; letter-spacing: 0; font-weight: 400; font-size: 15px; max-width: 70ch; }
20	  .directions { display: grid; grid-template-columns: 1fr; gap: 40px; }
21	  @media (min-width: 960px) { .directions { grid-template-columns: 1fr 1fr; gap: 32px; } }
22	  .dir-head { border-top: 2px solid var(--page-text); padding-top: 12px; margin-bottom: 16px; }
23	  .dir-head h2 { margin: 0; font-size: 20px; }
24	  .dir-head p { margin: 4px 0 0; color: var(--page-muted); font-size: 14px; }
25	  .variant { margin-bottom: 24px; }
26	  .variant-label { display: inline-block; margin: 0 0 8px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--page-muted); }
27	  .frame { border-radius: 14px; padding: 28px 20px; background: var(--bg); border: 1px solid var(--page-rule); }
28	  @media (min-width: 480px) { .frame { padding: 32px; } }
29	  .sr-note { font-size: 13px; color: var(--page-muted); margin: 8px 0 0; }
30	
31	  /* ---------- Direction A: Ledger ---------- */
32	  .a.light { --bg:#F5F3EE; --surface:#FFFFFF; --text:#1B1F24; --muted:#5A6069; --accent:#1F4E79;
33	    --pass:#1D6B3A; --pass-tint:#E6F2E9; --fail:#A8322D; --fail-tint:#FBE9E7; --border:#DDD8CD; --field-border:#8A9099;
34	    --shadow: 0 1px 2px rgba(27,31,36,.06), 0 8px 24px rgba(27,31,36,.06); }
35	  .a.dark { --bg:#111316; --surface:#1B1E23; --text:#ECEAE4; --muted:#A4A9B1; --accent:#8EB9E8;
36	    --pass:#6FCF97; --pass-tint:#16301F; --fail:#F2958D; --fail-tint:#3A1E1C; --border:#353A42; --field-border:#6E747E;
37	    --shadow: 0 1px 2px rgba(0,0,0,.4), 0 8px 24px rgba(0,0,0,.3); }
38	  .a .card { max-width: 420px; margin: 0 auto; background: var(--surface); color: var(--text); border: 1px solid var(--border); border-radius: 6px; box-shadow: var(--shadow); padding: 28px 24px 24px; }
39	  .a .eyebrow { margin: 0; font-size: 12px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }
40	  .a h3 { margin: 4px 0 22px; font-size: 20px; font-weight: 600; letter-spacing: -.005em; }
41	  .a .pair { display: grid; grid-template-columns: 1fr auto 1fr; align-items: end; gap: 10px; margin-bottom: 16px; }
42	  .a .of { padding-bottom: 12px; color: var(--muted); font-size: 15px; font-style: italic; }
43	  .a label { display: block; font-size: 13px; font-weight: 500; color: var(--muted); margin-bottom: 6px; }
44	  .a .field { position: relative; }
45	  .a input { width: 100%; min-height: 44px; padding: 0 12px; font: inherit; font-size: 17px; font-variant-numeric: tabular-nums; color: var(--text); background: var(--surface);
46	    border: 1px solid var(--field-border); border-radius: 4px; }
47	  .a .is-focus { outline: 2px solid var(--accent); outline-offset: 2px; }
48	  .a .suffix { position: absolute; right: 12px; bottom: 11px; color: var(--muted); font-size: 15px; }
49	  .a .pm { max-width: 140px; }
50	  .a .pm input { padding-right: 30px; }
51	  .a .rule { border: 0; border-top: 1px solid var(--border); margin: 24px 0 20px; }
52	  .a .result-label { margin: 0; font-size: 12px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }
53	  .a .score-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
54	  .a .score { margin: 0; font-size: 64px; line-height: 1.05; font-weight: 300; letter-spacing: -.03em; font-variant-numeric: tabular-nums lining-nums; }
55	  .a .score .pct { font-size: .5em; letter-spacing: 0; color: var(--muted); margin-left: 2px; }
56	  .a .verdict { display: inline-flex; align-items: center; gap: 6px; padding: 6px 14px 6px 10px; border-radius: 999px; font-weight: 700; font-size: 16px;
57	    color: var(--pass); background: var(--pass-tint); border: 1px solid currentColor; }
58	  .a .verdict svg { width: 18px; height: 18px; }
59	  .a .gap { margin: 8px 0 0; font-size: 15px; color: var(--text); }
60	  .a .gap .tick { color: var(--pass); font-weight: 700; margin-right: 4px; }
61	  .a .btn { margin-top: 22px; min-height: 44px; padding: 0 18px; font: inherit; font-size: 15px; font-weight: 600; color: var(--accent); background: transparent;
62	    border: 1px solid var(--accent); border-radius: 4px; }
63	  .a .hint { color: var(--muted); font-size: 13px; margin-left: 10px; }
64	  .a .hint kbd { font: inherit; font-size: 12px; border: 1px solid var(--border); border-bottom-width: 2px; border-radius: 3px; padding: 0 5px; color: var(--muted); }
