78	  .b .inputs { padding: 26px 22px 24px; color: var(--text); }
79	  .b h3 { margin: 0 0 20px; font-size: 22px; font-weight: 800; letter-spacing: -.02em; }
80	  .b h3 span { display: block; font-size: 13px; font-weight: 600; letter-spacing: 0; color: var(--muted); margin-top: 2px; }
81	  .b .field { margin-bottom: 14px; }
82	  .b label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 6px; color: var(--text); }
83	  .b .control { display: flex; align-items: center; min-height: 48px; border: 1.5px solid var(--field-border); border-radius: 12px; background: var(--field-bg); padding: 0 14px; }
84	  .b .control.is-focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--surface), 0 0 0 5px var(--accent); }
85	  .b input { flex: 1; min-width: 0; border: 0; background: transparent; font: inherit; font-size: 18px; font-weight: 600; color: var(--text); font-variant-numeric: tabular-nums; padding: 0; outline: none; width: 100%; }
86	  .b .unit { color: var(--muted); font-size: 14px; font-weight: 500; }
87	  .b .btn { width: 100%; min-height: 48px; margin-top: 8px; border: 0; border-radius: 12px; background: var(--accent); color: var(--on-accent); font: inherit; font-size: 16px; font-weight: 700; display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
88	  .b .btn svg { width: 18px; height: 18px; }
89	  .b .panel { background: var(--panel); color: var(--panel-text); padding: 28px 24px; display: flex; flex-direction: column; justify-content: center; margin: 0 10px 10px; border-radius: 14px; }
90	  .b .result-label { margin: 0; font-size: 13px; font-weight: 600; color: var(--panel-muted); }
91	  .b .score { margin: 4px 0 18px; font-size: clamp(48px, 11cqi, 80px); line-height: 1; font-weight: 800; letter-spacing: -.045em; font-variant-numeric: tabular-nums lining-nums; }
92	  .b .verdict { display: flex; align-items: center; gap: 10px; margin: 0; font-size: 26px; font-weight: 800; color: var(--pass); letter-spacing: -.01em; }
93	  .b .verdict svg { width: 30px; height: 30px; flex: none; }
