def lum(h):
    h=h.lstrip('#'); c=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    c=[x/12.92 if x<=0.04045 else ((x+0.055)/1.055)**2.4 for x in c]
    return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]
def cr(a,b):
    la,lb=sorted([lum(a),lum(b)],reverse=True); return (la+0.05)/(lb+0.05)
# (label, fg, bg, min)
D={
"A light":[("text/surface","#1B1F24","#FFFFFF",4.5),("text/bg","#1B1F24","#F5F3EE",4.5),
 ("muted/surface","#5A6069","#FFFFFF",4.5),("accent/surface","#1F4E79","#FFFFFF",4.5),
 ("pass/surface","#1D6B3A","#FFFFFF",4.5),("pass/pass-tint","#1D6B3A","#E6F2E9",4.5),
 ("fail/surface","#A8322D","#FFFFFF",4.5),("fail/fail-tint","#A8322D","#FBE9E7",4.5),
 ("field-border/surface (UI 3:1)","#8A9099","#FFFFFF",3.0),("focus=accent/surface (UI 3:1)","#1F4E79","#FFFFFF",3.0),
 ("border(hairline, decorative)","#DDD8CD","#FFFFFF",0)],
"A dark":[("text/surface","#ECEAE4","#1B1E23",4.5),("text/bg","#ECEAE4","#111316",4.5),
