 ("pass/surface","#6FCF97","#1B1E23",4.5),("pass/pass-tint","#6FCF97","#16301F",4.5),
 ("fail/surface","#F2958D","#1B1E23",4.5),("fail/fail-tint","#F2958D","#3A1E1C",4.5),
 ("field-border/surface (UI 3:1)","#6E747E","#1B1E23",3.0),("focus=accent/surface (UI 3:1)","#8EB9E8","#1B1E23",3.0),
 ("border(hairline, decorative)","#353A42","#1B1E23",0)],
"B light":[("text/surface","#161A33","#FFFFFF",4.5),("text/bg","#161A33","#ECEEF6",4.5),
 ("muted/surface","#535A76","#FFFFFF",4.5),("accent/surface","#4B3FD8","#FFFFFF",4.5),
 ("on-accent/accent (button)","#FFFFFF","#4B3FD8",4.5),
 ("panel-text/panel","#FFFFFF","#1F1B4E",4.5),("panel-muted/panel","#C9C6EE","#1F1B4E",4.5),
 ("pass/panel","#7FE0B0","#1F1B4E",4.5),("fail/panel","#FFA59C","#1F1B4E",4.5),
 ("pass/surface","#0E7A55","#FFFFFF",4.5),("fail(errors)/surface","#B42318","#FFFFFF",4.5),
 ("field-border/surface (UI 3:1)","#8A90A8","#FFFFFF",3.0),("focus=accent/surface (UI 3:1)","#4B3FD8","#FFFFFF",3.0),
 ("border(hairline, decorative)","#D6DAE7","#FFFFFF",0)],
"B dark":[("text/surface","#ECEEF8","#171A2E",4.5),("text/bg","#ECEEF8","#0C0E1A",4.5),
 ("muted/surface","#A3A8C3","#171A2E",4.5),("accent/surface","#A99FFF","#171A2E",4.5),
 ("on-accent/accent (button)","#14112E","#A99FFF",4.5),
 ("panel-text/panel","#FFFFFF","#2B2566",4.5),("panel-muted/panel","#D0CCF6","#2B2566",4.5),
 ("pass/panel","#86E5B6","#2B2566",4.5),("fail/panel","#FFAEA6","#2B2566",4.5),
 ("pass/surface","#86E5B6","#171A2E",4.5),("fail(errors)/surface","#FF9F96","#171A2E",4.5),
 ("field-border/surface (UI 3:1)","#6C7294","#171A2E",3.0),("focus=accent/surface (UI 3:1)","#A99FFF","#171A2E",3.0),
 ("border(hairline, decorative)","#2D3252","#171A2E",0)],
}
bad=0
for k,v in D.items():
    print(f"## {k}")
    for lab,f,b,m in v:
        r=cr(f,b); ok="PASS" if r>=m else "FAIL"
        if r<m: bad+=1
        print(f"  {lab:34s} {f} on {b}  {r:5.2f}:1  min {m}  {ok if m else 'n/a'}")
print("FAILS:",bad)
const { chromium } = require('/opt/node-tools/node_modules/playwright');
const path = require('path');
(async () => {
  const root = '/home/user/Web-Calculator-fresh/sabee-khan-calculator/docs/process/design';
  const browser = await chromium.launch();
  for (const w of [1280, 375]) {
    const page = await browser.newPage({ viewport: { width: w, height: 900 } });
    const errs = [];
    page.on('console', m => errs.push(m.type() + ': ' + m.text()));
    page.on('requestfailed', r => errs.push('reqfail ' + r.url()));
    await page.goto('file://' + path.join(root, 'directions.html'));
    const sw = await page.evaluate(() => document.documentElement.scrollWidth);
    await page.screenshot({ path: path.join(root, 'screenshots', `directions-${w}.png`), fullPage: true });
    console.log(w, 'scrollWidth', sw, 'console', errs);
    await page.close();
  }
  await browser.close();
})();
from decimal import Decimal as D, ROUND_FLOOR, ROUND_CEILING
def fmt_gap(x):
    s = f"{x:,.2f}"
    if '.' in s: s = s.rstrip('0').rstrip('.')
    return s
def calc(e, t, p, ref):
    e, t = D(e), D(t)
    score = e / t * 100            # exact enough at 28 digits for display
    shown = (e * 1000 / t).to_integral_value(rounding=ROUND_FLOOR) / 10
    shown_s = f"{shown:.1f}%"
    if p is None:
        print(f"{ref:8} {e} of {t}, pass mark empty -> {shown_s}"); return
    p = D(p)
    verdict = "Pass" if e * 100 >= p * t else "Fail"   # exact integer-free compare
    needed = p / 100 * t
    gap = e - needed
    if gap == 0: g = "Exactly on the pass mark"
    elif gap < 0:
        v = (-gap).quantize(D('0.01'), rounding=ROUND_CEILING)
        g = f"{fmt_gap(v)} mark{'' if v == 1 else 's'} short of the pass mark"
    else:
        v = gap.quantize(D('0.01'), rounding=ROUND_FLOOR)
        g = "Less than 0.01 marks above the pass mark" if v == 0 else f"{fmt_gap(v)} mark{'' if v == 1 else 's'} above the pass mark"
    print(f"{ref:8} {e} of {t}, pass {p}: exact={score.normalize()}% shown={shown_s} {verdict} | needed={needed.normalize()} gap={gap.normalize()} -> {g}")
