#!/usr/bin/env python3
"""Generates docs/process/design/mockup.html (static HTML+CSS, no scripts).
Message texts are taken from the catalogue in docs/user-stories.md so they match character for character."""
import re, html, pathlib

PKG = pathlib.Path('/home/user/Web-Calculator-fresh/sabee-khan-calculator')
OUT = PKG / 'docs/process/design/mockup.html'
cat = {}
for line in (PKG / 'docs/user-stories.md').read_text(encoding='utf-8').splitlines():
    m = re.match(r'\| (M-\d+) \| [^|]+ \| "(.*)" \|$', line)
    if m:
        cat[m.group(1)] = m.group(2)
assert len(cat) == 29, len(cat)

def M(mid, n=None):
    t = cat[mid]
    if n is not None:
        t = t.replace('{n}', n)
    return f'<span data-m="{mid}">{html.escape(t, quote=False)}</span>'

# ---------- icons (decorative, aria-hidden) ----------
TICK = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path class="i-stroke" d="M6.5 12.5l3.8 3.8 7.4-8.3"/></svg>'
CROSS = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path class="i-stroke" d="M8 8l8 8M16 8l-8 8"/></svg>'
UP = '<svg class="gap-icon gap-icon--pass" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 3.5l5 7H3z"/></svg>'
DOWN = '<svg class="gap-icon gap-icon--fail" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 12.5l5-7H3z"/></svg>'
EQ = '<svg class="gap-icon gap-icon--pass" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 5.5h10v2H3zM3 9.5h10v2H3z"/></svg>'
ALERT = '<svg class="alert-icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><circle cx="8" cy="8" r="7"/><path class="alert-mark" d="M8 4.4v4.4"/><circle class="alert-dot" cx="8" cy="11.4" r="1.05"/></svg>'

uid = [0]
def nid(p):
    uid[0] += 1
    return f'{p}-{uid[0]}'

def field(kind, label_html, value, error_mid=None, focus=False, hover=False, suffix=False):
    i = nid(kind)
    err_id = f'{i}-error'
    cls = ['input']
    if focus: cls.append('is-focus')
    if hover: cls.append('is-hover')
    aria = f' aria-describedby="{err_id}"'
    if error_mid:
        aria += ' aria-invalid="true"'
    inp = (f'<input class="{" ".join(cls)}" id="{i}" type="text" inputmode="decimal" autocomplete="off" '
           f'value="{html.escape(value)}"{aria}>')
    if suffix:
        inp = f'<div class="input-wrap">{inp}<span class="suffix" aria-hidden="true">%</span></div>'
    err = f'{ALERT}{M(error_mid)}' if error_mid else ''
    return (f'<div class="field field--{kind}"><label class="label" for="{i}">{label_html}</label>{inp}'
            f'<p class="field-error" id="{err_id}">{err}</p></div>')

def verdict(kind):
    if kind == 'pass':
        return f'<p class="verdict verdict--pass"><span class="verdict-disc">{TICK}</span>{M("M-4")}</p>'
    return f'<p class="verdict verdict--fail"><span class="verdict-disc">{CROSS}</span>{M("M-5")}</p>'

def score(s):
    return f'<p class="score">{s}<span class="pct">%</span></p>'

def result_body(state):
    if state == 'idle':
        return f'<p class="result-msg">{M("M-1")}</p>'
    if state == 'pass':
        return (f'<div class="outcome">{score("76.0")}{verdict("pass")}'
                f'<p class="gap">{UP}{M("M-8", "1.4")}</p></div>')
    if state == 'fail':
        return (f'<div class="outcome">{score("67.3")}{verdict("fail")}'
                f'<p class="gap">{DOWN}{M("M-6", "0.6")}</p></div>')
    if state == 'error':
        return f'<p class="result-msg result-msg--error">{ALERT}{M("M-3")}</p>'
    if state == 'nopass':
        return f'<div class="outcome">{score("76.0")}<p class="verdict-msg">{M("M-2")}</p></div>'

STATES = {
    'idle':   ('a', 'Idle / empty', 'Page just opened: marks earned and total empty, pass mark pre-filled "70" (M-1).', ('', '', '70'), None, False),
    'pass':   ('b', 'Pass result', '17.5 of 23, pass mark 70 → 76.0%, Pass, M-8. Cursor in marks earned (focus ring).', ('17.5', '23', '70'), None, True),
    'fail':   ('c', 'Fail result', '15.5 of 23, pass mark 70 → 67.3%, Fail, M-6.', ('15.5', '23', '70'), None, False),
    'error':  ('d', 'Error', '23.5 of 23 → M-15 under marks earned (aria-invalid), M-3 in the result area, no score.', ('23.5', '23', '70'), 'M-15', True),
    'nopass': ('e', 'Pass mark empty', '17.5 of 23, pass mark cleared → score still shown, M-2 in the verdict slot, no gap line, no error.', ('17.5', '23', ''), None, False),
}

def card(state):
    letter, name, note, (e, t, p), err, focus = STATES[state]
    title_id = nid('title')
    score_id = nid('score-label')
    return f'''<article class="card" aria-labelledby="{title_id}">
  <header class="card-head"><p class="eyebrow">Quiz score</p><h1 class="title" id="{title_id}">Check a quiz result</h1><p class="sub">A score at or above the pass mark is a pass.</p></header>
  <div class="fields">
    {field('earned', 'Marks earned', e, err, focus=focus)}
    <span class="of" aria-hidden="true">of</span>
    {field('total', 'Total marks possible', t)}
    {field('passmark', 'Pass mark<span class="sr-only"> (percent)</span>', p, suffix=True)}
  </div>
  <hr class="rule">
  <section class="result" aria-labelledby="{score_id}">
    <p class="eyebrow" id="{score_id}">Score</p>
    <div class="result-body">{result_body(state)}</div>
  </section>
  <div class="actions"><button class="btn" type="button" aria-keyshortcuts="Escape">{M("M-25")}</button><span class="hint">or press <kbd>Esc</kbd></span></div>
</article>'''

def state_head(state):
    letter, name, note, *_ = STATES[state]
    return f'<h3 class="state-title"><span class="state-letter">({letter})</span> {name}</h3><p class="state-note">{html.escape(note)}</p>'

order = ['idle', 'pass', 'fail', 'error', 'nopass']

desktop = []
for s in order:
    cells = ''.join(
        f'<div class="theme-cell"><p class="theme-label">{th.capitalize()}</p><div class="theme theme--{th} viewport"><div class="app">{card(s)}</div></div></div>'
        for th in ('light', 'dark'))
    desktop.append(f'<div class="state" id="desktop-{s}">{state_head(s)}<div class="pair">{cells}</div></div>')

mobile = []
for th in ('light', 'dark'):
    frames = ''.join(
        f'<figure class="device-fig"><figcaption class="device-cap"><span class="state-letter">({STATES[s][0]})</span> {STATES[s][1]} · {th}</figcaption>'
        f'<div class="theme theme--{th} viewport device"><div class="app">{card(s)}</div></div></figure>'
        for s in order)
    mobile.append(f'<h3 class="strip-title">Mobile, {th} theme</h3><div class="devices">{frames}</div>')

def states_strip(th):
    inputs = ''.join(f'<div class="demo"><p class="demo-cap">{cap}</p>{f}</div>' for cap, f in [
        ('Input · default (empty)', field('demo', 'Marks earned', '')),
        ('Input · hover', field('demo', 'Marks earned', '', hover=True)),
        ('Input · focus-visible', field('demo', 'Marks earned', '17.5', focus=True)),
        ('Input · filled', field('demo', 'Total marks possible', '23')),
        ('Input · error (M-12)', field('demo', 'Marks earned', 'abc', 'M-12')),
        ('Input · suffix', field('demo', 'Pass mark<span class="sr-only"> (percent)</span>', '70', suffix=True)),
    ])
    btns = ''.join(f'<div class="demo"><p class="demo-cap">Button · {c}</p><button class="btn {k}" type="button">{M("M-25")}</button></div>'
                   for c, k in [('default', ''), ('hover', 'is-hover'), ('focus-visible', 'is-focus'), ('active', 'is-active')])
    gaps = ''.join(f'<p class="gap">{icon}{txt}</p>' for icon, txt in [
        (UP, M('M-8', '1.4')), (UP, M('M-9')), (DOWN, M('M-6', '0.6')), (DOWN, M('M-7')), (EQ, M('M-10')), (UP, M('M-11'))])
    return f'''<div class="theme-cell"><p class="theme-label">{th.capitalize()}</p><div class="theme theme--{th} viewport"><div class="app"><div class="card states-card">
  <div class="demo-grid">{inputs}</div>
  <div class="demo-row">{btns}</div>
  <div class="demo-row demo-row--verdicts"><div class="demo"><p class="demo-cap">Verdict · Pass</p>{verdict('pass')}</div><div class="demo"><p class="demo-cap">Verdict · Fail</p>{verdict('fail')}</div></div>
  <div class="demo"><p class="demo-cap">Gap line · M-8, M-9, M-6, M-7, M-10, M-11</p>{gaps}</div>
</div></div></div></div>'''

CSS = r'''
