const { chromium } = require(require('child_process').execSync('npm root -g').toString().trim() + '/playwright');
const path = require('path');
const root = '/home/user/Web-Calculator-fresh/sabee-khan-calculator/docs/process/design';
const msgs = {
  earned: ["Marks earned must be a number, like 17.5.","Marks earned can't be negative.","Marks earned can have at most 2 decimal places.","Marks earned can't be more than the total marks possible."],
  total: ["Total marks possible must be a number, like 23.","Total marks possible can't be negative.","Total marks possible can have at most 2 decimal places.","Total marks possible must be more than 0.","Total marks possible can't be more than 1,000,000."],
  passmark: ["Pass mark must be a number, like 70.","Pass mark can't be negative.","Pass mark can have at most 1 decimal place.","Pass mark can't be more than 100."],
};
const gaps = ["699,999.99 marks short of the pass mark","Less than 0.01 marks above the pass mark","1,000,000 marks above the pass mark"];
(async () => {
  const browser = await chromium.launch();
  for (const w of [1280, 375, 320]) {
    const page = await browser.newPage({ viewport: { width: w, height: 900 } });
    const errs = [];
    page.on('console', m => errs.push(m.type() + ': ' + m.text()));
    page.on('request', r => { if (!r.url().startsWith('file:')) errs.push('external request ' + r.url()); });
    await page.goto('file://' + path.join(root, 'mockup.html'));
    const sw = await page.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
    if (w !== 320) await page.screenshot({ path: path.join(root, 'screenshots', `mockup-${w}.png`), fullPage: true });
    // layout stability: per frame width group, result-body height and actions offset
    const stab = await page.evaluate(() => {
      const out = {};
      document.querySelectorAll('.viewport').forEach(v => {
        const card = v.querySelector('article.card'); if (!card) return;
        const key = (v.classList.contains('device') ? 'device' : 'desktop') + '@' + Math.round(v.getBoundingClientRect().width);
        const rb = card.querySelector('.result-body').getBoundingClientRect().height;
        const act = card.querySelector('.actions').getBoundingClientRect().top - card.getBoundingClientRect().top;
        const h = card.getBoundingClientRect().height;
        (out[key] ||= new Set()).add(`body=${rb.toFixed(1)} actionsTop=${act.toFixed(1)} card=${h.toFixed(1)}`);
      });
      return Object.fromEntries(Object.entries(out).map(([k, s]) => [k, [...s]]));
    });
    // fit test: every field message within its 2-line slot, every gap text within reserved result height
    const fit = await page.evaluate(({ msgs, gaps }) => {
      const bad = [];
      document.querySelectorAll('.viewport article.card:not(.states-card)').forEach((card, ci) => {
        for (const [kind, list] of Object.entries(msgs)) {
          const slot = card.querySelector(`.field--${kind} .field-error`);
          const min = parseFloat(getComputedStyle(slot).minHeight);
          const old = slot.innerHTML;
          for (const t of list) { slot.textContent = t; if (slot.getBoundingClientRect().height > min + 0.5) bad.push(`card${ci} ${kind} '${t}' h=${slot.getBoundingClientRect().height} > ${min}`); }
          slot.innerHTML = old;
        }
        const gap = card.querySelector('.gap'); const body = card.querySelector('.result-body');
        if (gap) { const min = parseFloat(getComputedStyle(body).minHeight); const old = gap.innerHTML;
          for (const t of gaps) { gap.lastElementChild.textContent = t; if (body.getBoundingClientRect().height > min + 0.5) bad.push(`card${ci} gap '${t}' body=${body.getBoundingClientRect().height} > ${min}`); }
          gap.innerHTML = old; }
        const sc = card.querySelector('.score');
        if (sc) { const old = sc.innerHTML; sc.innerHTML = '100.0<span class="pct">%</span>';
          if (sc.scrollWidth > sc.parentElement.clientWidth) bad.push(`card${ci} score 100.0% overflows`);
          const body = card.querySelector('.result-body'); if (body.getBoundingClientRect().height > parseFloat(getComputedStyle(body).minHeight) + 0.5) bad.push(`card${ci} 100.0% grows body`);
          sc.innerHTML = old; }
      });
      return bad;
    }, { msgs, gaps });
    const tgt = await page.evaluate(() => [...document.querySelectorAll('input,button')].filter(e => { const r = e.getBoundingClientRect(); return r.height < 44 || r.width < 44; }).length);
    console.log(`--- ${w}px: scrollWidth/clientWidth ${sw} | console/external: ${JSON.stringify(errs)} | targets <44px: ${tgt}`);
    console.log(' stability:', JSON.stringify(stab));
    console.log(' fit issues:', fit.length ? fit.slice(0, 12).join('\n  ') + ` (total ${fit.length})` : 'none');
    await page.close();
  }
  await browser.close();
})();
EOF
