import re, sys
from html.parser import HTMLParser
PKG='/home/user/Web-Calculator-fresh/sabee-khan-calculator/'
cat={}
for line in open(PKG+'docs/user-stories.md',encoding='utf-8'):
    m=re.match(r'\| (M-\d+) \| [^|]+ \| "(.*)" \|$', line.rstrip('\n'))
    if m: cat[m.group(1)]=m.group(2)
class P(HTMLParser):
    def __init__(s): super().__init__(); s.stack=[]; s.found=[]; s.scripts=0; s.ext=[]
    def handle_starttag(s,t,a):
        a=dict(a)
        if t=='script': s.scripts+=1
        for k in ('src','href'):
            if k in a: s.ext.append(a[k])
        if t in ('input','svg','path','circle','meta','hr','br'): 
            if t not in ('svg',): return
        s.stack.append([a.get('data-m'),''] if 'data-m' in a else None)
    def handle_endtag(s,t):
        if t in ('input','path','circle','meta','hr','br'): return
        e=s.stack.pop()
        if e: s.found.append((e[0],e[1]))
    def handle_data(s,d):
        for e in s.stack:
            if e: e[1]+=d
p=P(); src=open(PKG+'docs/process/design/mockup.html',encoding='utf-8').read(); p.feed(src)
bad=0; seen={}
for mid,txt in p.found:
    tpl=cat[mid]
    if '{n}' in tpl:
        rx='^'+re.escape(tpl).replace(re.escape('{n}'),r'(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?)')+'$'
        ok=re.match(rx,txt) is not None
    else: ok= txt==tpl
    seen.setdefault(mid,set()).add(txt)
    if not ok: bad+=1; print('MISMATCH',mid,repr(txt),'expected',repr(tpl))
for mid in sorted(seen,key=lambda x:int(x[2:])):
    print(f'{mid}: {len(seen[mid])} distinct text(s), e.g. "{sorted(seen[mid])[0]}" -> matches catalogue')
print('occurrences checked:',len(p.found),'mismatches:',bad,'| <script> tags:',p.scripts,'| src/href attrs:',p.ext)
print('url( / @import / http in file:', len(re.findall(r'url\(|@import|https?://',src)))
EOF
python3 msgcheck.py

